#define main unused_fit_main
#include "fit_metrics.cpp"
#undef main
#include <limits>
double surfaceDistance(const Mesh& m,Vec p){double best=1e100;for(auto f:m.faces){auto a=m.vertices[f[0]],b=m.vertices[f[1]],c=m.vertices[f[2]],u=b-a,v=c-a,n=cross(u,v);double n2=dot(n,n);if(n2>1e-20){auto q=p-n*(dot(p-a,n)/n2);auto w=q-a;double uu=dot(u,u),vv=dot(v,v),uv=dot(u,v),uw=dot(u,w),vw=dot(v,w),den=uu*vv-uv*uv;if(den>1e-20){double s=(uw*vv-vw*uv)/den,t=(vw*uu-uw*uv)/den;if(s>=0&&t>=0&&s+t<=1)best=std::min(best,length(p-q));}}for(auto edge:{std::pair{a,b},std::pair{b,c},std::pair{c,a}}){auto d=edge.second-edge.first;double den=dot(d,d);double t=den>0?std::clamp(dot(p-edge.first,d)/den,0.,1.):0.;best=std::min(best,length(p-(edge.first+d*t)));}}return best;}
int main(int argc,char** argv){try{Input init;init.sources={boxSource({1,1,1})};joltCollisionGeometry(init);Json report=Json::array();for(Vec p:std::vector<Vec>{{-1.3,0,1.0},{-1.25,0,.9},{-1.35,0,1.15}}){Json row={{"point_m",{p.x,p.y,p.z}},{"inside",Json::array()}};for(int quality=0;quality<3;++quality){Json j;std::ifstream(std::filesystem::path(argv[1])/("teapot_q"+std::to_string(quality)+"-result.json"))>>j;auto in=decodeInput(j["input"]);row["inside"].push_back(inside(planes(in.sources[0]),p));row["nearest_render_surface_m"]=surfaceDistance(in.sources[0].render,p);}report.push_back(row);}std::ofstream(argv[2])<<report.dump(2);std::cout<<report.dump(2);return 0;}catch(const std::exception& e){std::cerr<<e.what();return 1;}}
